      "severity": "medium",
      "description": "Format B reads the entire JSONL file into memory instead of streaming line by line."
    },
    {
      "file": "evalmerge/parsers.py",
      "lines": "88-91",
      "severity": "medium",
      "description": "Format A parses CSV one physical line at a time, so valid quoted fields containing newlines are misparsed."
    },
    {
      "file": "evalmerge/report.py",
      "lines": "17-23",
      "severity": "medium",
      "description": "The report omits sources with zero persisted rows, which can hide missing or failed source ingestion."
