    },
    {
      "file": "tests/test_pipeline.py",
      "lines": "37-193",
      "severity": "medium",
      "description": "Pipeline tests cover generated fixtures but miss malformed object shapes, malformed XML, non-finite scores, and stale-row reingest behavior."
    },
    {
      "file": "pyproject.toml",
